/**
 * Main App Component
 * 
 * This is the root component of the React frontend.
 * It manages the overall application state and renders the main UI.
 * 
 * Data Flow:
 * User Interaction -> Component State -> API Calls -> Backend
 * User Interaction <- Component State <- API Response <- Backend
 */

import React, { useState, useEffect } from 'react';
import axios from 'axios';
import './App.css';

// Component imports
import DataForm from './components/DataForm';
import DataList from './components/DataList';
import SearchBar from './components/SearchBar';

function App() {
  // State management for data records
  const [records, setRecords] = useState([]);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState('');
  const [editingRecord, setEditingRecord] = useState(null);
  const [searchTerm, setSearchTerm] = useState('');

  // Base URL for API calls
  const API_URL = '/api/data';

  /**
   * Fetch all records from the backend
   * This function is called on component mount and when search term changes
   */
  const fetchRecords = async () => {
    try {
      setLoading(true);
      setError('');

      // Include search term in query if exists
      const url = searchTerm ? `${API_URL}?search=${encodeURIComponent(searchTerm)}` : API_URL;

      const response = await axios.get(url);

      if (response.data.success) {
        setRecords(response.data.data);
      } else {
        setError('Failed to fetch records');
      }
    } catch (err) {
      setError('Error connecting to server. Please make sure the backend is running.');
      console.error('Fetch error:', err);
    } finally {
      setLoading(false);
    }
  };

  /**
   * Create or update a record
   * @param {Object} recordData - The record data to save
   */
  const saveRecord = async (recordData) => {
    try {
      setLoading(true);
      setError('');

      let response;

      if (editingRecord) {
        // Update existing record
        response = await axios.put(`${API_URL}/${editingRecord._id}`, recordData);
      } else {
        // Create new record
        response = await axios.post(API_URL, recordData);
      }

      if (response.data.success) {
        // Reset form and refresh records
        setEditingRecord(null);
        fetchRecords();
      } else {
        setError('Failed to save record');
      }
    } catch (err) {
      setError(err.response?.data?.message || 'Error saving record');
      console.error('Save error:', err);
    } finally {
      setLoading(false);
    }
  };

  /**
   * Delete a record
   * @param {string} id - The ID of the record to delete
   */
  const deleteRecord = async (id) => {
    if (!window.confirm('Are you sure you want to delete this record?')) {
      return;
    }

    try {
      setLoading(true);
      setError('');

      const response = await axios.delete(`${API_URL}/${id}`);

      if (response.data.success) {
        fetchRecords();
      } else {
        setError('Failed to delete record');
      }
    } catch (err) {
      setError(err.response?.data?.message || 'Error deleting record');
      console.error('Delete error:', err);
    } finally {
      setLoading(false);
    }
  };

  /**
   * Handle edit button click
   * @param {Object} record - The record to edit
   */
  const handleEdit = (record) => {
    setEditingRecord(record);
  };

  /**
   * Handle cancel edit
   */
  const handleCancelEdit = () => {
    setEditingRecord(null);
  };

  /**
   * Handle search term change
   * @param {string} term - The search term
   */
  const handleSearch = (term) => {
    setSearchTerm(term);
  };

  // Fetch records on component mount and when search term changes
  useEffect(() => {
    fetchRecords();
  }, [searchTerm]);

  return (
    <div className="App">
      <header className="App-header">
        <h1>Personal Data Manager</h1>
        <p>Manage your personal data with ease</p>
      </header>

      <main className="App-main">
        {/* Error Display */}
        {error && (
          <div className="error-message">
            {error}
            <button onClick={() => setError('')} className="close-error">×</button>
          </div>
        )}

        {/* Loading Indicator */}
        {loading && (
          <div className="loading-indicator">
            <div className="spinner"></div>
            <span>Loading...</span>
          </div>
        )}

        {/* Search Bar */}
        <SearchBar 
          onSearch={handleSearch} 
          searchTerm={searchTerm}
          disabled={loading}
        />

        {/* Data Form - for creating and editing records */}
        <DataForm 
          onSave={saveRecord}
          editingRecord={editingRecord}
          onCancelEdit={handleCancelEdit}
          disabled={loading}
        />

        {/* Data List - displays all records */}
        <DataList 
          records={records}
          onEdit={handleEdit}
          onDelete={deleteRecord}
          disabled={loading}
        />
      </main>

      <footer className="App-footer">
        <p>Built with React, Node.js, Express, and MongoDB</p>
      </footer>
    </div>
  );
}

export default App;
